const listContacts = `-- name: ListContacts :many


WITH vis AS (
    SELECT c.id FROM contacts c
    WHERE c.tenant_id = $2 AND (
        c.owner_user_id = $1
        OR EXISTS (
            SELECT 1 FROM contact_group_members m
            JOIN contact_group_shares s ON s.group_id = m.group_id
            JOIN user_group_members ugm ON ugm.group_id = s.user_group_id
            WHERE m.contact_id = c.id AND ugm.user_id = $1)
        OR EXISTS (
            SELECT 1 FROM contact_group_members m
            JOIN contact_group_user_shares us ON us.group_id = m.group_id
            WHERE m.contact_id = c.id AND us.user_id = $1)
    )
)
SELECT c.id, c.tenant_id, c.owner_user_id, c.name, c.email, c.phone, c.company, c.notes, c.tags, c.created_at, c.title, c.mobile, c.is_whatsapp, c.kind, c.company_id, c.domain, c.allow_phone, c.allow_email, c.extra_emails, c.extra_phones, c.custom_fields, c.avatar_file_id, co.name AS company_name
FROM contacts c
LEFT JOIN contacts co ON co.id = c.company_id
WHERE c.tenant_id = $2
  AND (c.id IN (SELECT id FROM vis) OR c.company_id IN (SELECT id FROM vis))
ORDER BY c.name
`

type ListContactsParams struct {
	OwnerUserID uuid.UUID `json:"owner_user_id"`
	TenantID    uuid.UUID `json:"tenant_id"`
}

type ListContactsRow struct {
	ID           uuid.UUID       `json:"id"`
	TenantID     uuid.UUID       `json:"tenant_id"`
	OwnerUserID  uuid.UUID       `json:"owner_user_id"`
	Name         string          `json:"name"`
	Email        string          `json:"email"`
	Phone        string          `json:"phone"`
	Company      string          `json:"company"`
	Notes        string          `json:"notes"`
	Tags         []string        `json:"tags"`
	CreatedAt    time.Time       `json:"created_at"`
	Title        string          `json:"title"`
	Mobile       string          `json:"mobile"`
	IsWhatsapp   bool            `json:"is_whatsapp"`
	Kind         string          `json:"kind"`
	CompanyID    pgtype.UUID     `json:"company_id"`
	Domain       string          `json:"domain"`
	AllowPhone   bool            `json:"allow_phone"`
	AllowEmail   bool            `json:"allow_email"`
	ExtraEmails  []string        `json:"extra_emails"`
	ExtraPhones  []string        `json:"extra_phones"`
	CustomFields json.RawMessage `json:"custom_fields"`
	AvatarFileID pgtype.UUID     `json:"avatar_file_id"`
	CompanyName  *string         `json:"company_name"`
}

// ===== Contacts (N:N groups + tags) =====
// VISIBILITY RULE (repeated in every contact read):
//
//	tenant  → everyone in the organization sees it
//	private → owner only
//	groups  → the owner + anyone in a group the contact was shared with
//
// ALWAYS read through here; never by owner_user_id alone (it would hide what is shared) nor
// by tenant_id alone (it would leak what is private).
// VISIBILITY BY GROUP: I see the contact if I am the owner, or if I am on a TEAM that one of its
// GROUPS was shared with. A person inherits from the company: seeing Acme means seeing who works
// there — otherwise the list would show the company and hide its people (the "of —" bug coming back).
func (q *Queries) ListContacts(ctx context.Context, arg ListContactsParams) ([]ListContactsRow, error) {
	rows, err := q.db.Query(ctx, listContacts, arg.OwnerUserID, arg.TenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListContactsRow
	for rows.Next() {
		var i ListContactsRow
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.OwnerUserID,
			&i.Name,
			&i.Email,
			&i.Phone,
			&i.Company,
			&i.Notes,
			&i.Tags,
			&i.CreatedAt,
			&i.Title,
			&i.Mobile,
			&i.IsWhatsapp,
			&i.Kind,
			&i.CompanyID,
			&i.Domain,
			&i.AllowPhone,
			&i.AllowEmail,
			&i.ExtraEmails,
			&i.ExtraPhones,
			&i.CustomFields,
			&i.AvatarFileID,
			&i.CompanyName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

