const usersForMailPush = `-- name: UsersForMailPush :many
SELECT DISTINCT u.id, u.tenant_id, u.jmap_cred, u.mail_seen_at
FROM mail_users u JOIN push_subscriptions p ON p.user_id = u.id
WHERE u.jmap_cred <> '' AND u.presence <> 'dnd'
`

type UsersForMailPushRow struct {
	ID         uuid.UUID          `json:"id"`
	TenantID   uuid.UUID          `json:"tenant_id"`
	JmapCred   string             `json:"jmap_cred"`
	MailSeenAt pgtype.Timestamptz `json:"mail_seen_at"`
}

// Users eligible for new-email push: they have a JMAP credential (brokering), at least one push
// subscription, and are not in Do Not Disturb. mail_seen_at is the basis for the last check.
func (q *Queries) UsersForMailPush(ctx context.Context) ([]UsersForMailPushRow, error) {
	rows, err := q.db.Query(ctx, usersForMailPush)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UsersForMailPushRow
	for rows.Next() {
		var i UsersForMailPushRow
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.JmapCred,
			&i.MailSeenAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
